    customerId: 'C-001', // Gold tier (5%)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });

  assert.equal(invoice.ok, true);
  const totals = invoiceTotals(invoice.value);
  assert.equal(totals.ok, true);
  // Subtotal: 5*9500 + 3*8500 = 47500 + 25500 = 73000
  // Discount: 73000 * 5% = 3650
  // Net: 73000 - 3650 = 69350
  // VAT: roundCents(69350 * 21 / 100) = 14563 (due to floating point precision)
  // Total: 73000 - 3650 + 14563 = 83913
  assert.equal(totals.value.subtotal, 73000);
  assert.equal(totals.value.discount, 3650);
  assert.equal(totals.value.vat, 14563);
  assert.equal(totals.value.total, 83913);
});

